@Bean
public PasswordEncoder passwordEncoder() {
    String idForEncode = "argon2";
    Map<String, PasswordEncoder> encoders = new HashMap<>();
    encoders.put("argon2", Argon2PasswordEncoder.defaultsForSpringSecurity_v5_8());
    encoders.put("bcrypt", new BCryptPasswordEncoder(12));
    encoders.put("pbkdf2", Pbkdf2PasswordEncoder.defaultsForSpringSecurity_v5_8());
    // 输出格式：{argon2}$argon2id$v=19$m=16384,t=2,p=1$...$...
    return new DelegatingPasswordEncoder(idForEncode, encoders);
}

public boolean authenticate(String username, String rawPassword) {
    UserCredential cred = repo.findByUsername(username);
    if (cred == null) {
        // 用户不存在仍跑一次 hash，避免响应时间泄露用户存在性
        encoder.matches(rawPassword, DUMMY_HASH);
        rateLimiter.recordFailure(username);
        return false;
    }
    if (!encoder.matches(rawPassword, cred.getHash())) {
        rateLimiter.recordFailure(username);
        return false;
    }
    // 命中后判断旧前缀或弱参数，登录瞬间升级
    if (encoder.upgradeEncoding(cred.getHash())) {
        cred.setHash(encoder.encode(rawPassword));
        cred.setHashUpgradedAt(Instant.now());
        repo.save(cred);
    }
    rateLimiter.recordSuccess(username);
    return true;
}
